#include <stdio.h>

int main(void) {
    int data[] = { 5, 10, 15, 20 };
    size_t count = sizeof data / sizeof data[0];
    for (size_t i = 0; i < count; ++i) {
        printf("index %zu: %d\n", i, data[i]);
    }
    return 0;
}

#include <stddef.h>
#include <stdio.h>

void print_values(const int values[], size_t count) {
    for (size_t i = 0; i < count; ++i) {
        printf("%d\n", values[i]);
    }
}

int main(void) {
    int values[] = { 2, 4, 6 };
    print_values(values, sizeof values / sizeof values[0]);
    return 0;
}
